<script setup lang="ts">
import { computed, ref, watch } from 'vue'
import { ArrowRight, CircleAlert, GripVertical, Route } from '@lucide/vue'
import type { LearnObjectiveSnapshot, LearnMasteryState } from '~/types/learn-v2-journey'
const { objectives, selectedObjectiveId = null } = defineProps<{ objectives: LearnObjectiveSnapshot[]; selectedObjectiveId?: string | null }>()
const emit = defineEmits<{ selectObjective: [objectiveId: string]; editObjective: [objectiveId: string]; addObjective: []; regenerate: []; saveObjective: [payload: { objectiveId?: string; title: string; capability: string }] }>()
const selected = computed(() => objectives.find(item => item.id === selectedObjectiveId) ?? objectives[0] ?? null)
const editor = ref<{ objectiveId?: string; title: string; capability: string } | null>(null)
watch(selected, item => { if (editor.value?.objectiveId === item?.id) editor.value = item ? { objectiveId: item.id, title: item.title, capability: item.capability } : null }, { flush: 'sync' })
function editSelected() { if (!selected.value) return; editor.value = { objectiveId: selected.value.id, title: selected.value.title, capability: selected.value.capability } }
function addNew() { editor.value = { title: '', capability: '' } }
function save() { if (!editor.value?.title.trim() || !editor.value.capability.trim()) return; emit('saveObjective', { ...editor.value, title: editor.value.title.trim(), capability: editor.value.capability.trim() }); editor.value = null }
const stateLabel: Record<LearnMasteryState, string> = { unseen: 'Not started', learning: 'Learning', guided: 'Guided', independent: 'Independent', retained: 'Retained', needs_review: 'Needs review', blocked: 'Blocked', provisionally_known: 'Provisionally known' }
const coverageClass = { strong: 'text-emerald-300', partial: 'text-amber-300', gap: 'text-rose-300' }
</script>
<template>
  <section data-testid="learn-v2-learning-trail"><header class="flex flex-col gap-3 sm:flex-row sm:items-end sm:justify-between"><div><p class="font-inter text-xs uppercase tracking-wide text-primary">Learning map</p><h2 class="mt-1 font-dm-sans text-xl font-bold">Build the trail to your outcome</h2><p class="mt-1 text-sm text-muted-foreground">Objectives remain editable. Evidence, prerequisite, or assessment changes become a new draft revision.</p></div><div class="flex gap-2"><UiButton variant="secondary" size="sm" data-testid="learn-v2-map-regenerate" @click="emit('regenerate')">Refresh map</UiButton><UiButton size="sm" data-testid="learn-v2-map-add-objective" @click="addNew">Add objective</UiButton></div></header><div v-if="editor" class="mt-5 rounded-xl border border-primary/30 bg-card p-5" data-testid="learn-v2-objective-editor"><h3 class="font-dm-sans text-lg font-semibold">{{ editor.objectiveId ? 'Edit objective' : 'Add objective' }}</h3><label class="mt-4 block text-sm font-medium">Objective title<input v-model="editor.title" data-testid="learn-v2-objective-title" class="mt-1.5 w-full rounded-lg border border-input bg-background px-3 py-2" maxlength="200"></label><label class="mt-4 block text-sm font-medium">Capability<input v-model="editor.capability" data-testid="learn-v2-objective-capability" class="mt-1.5 w-full rounded-lg border border-input bg-background px-3 py-2" maxlength="500"></label><div class="mt-5 flex justify-end gap-2"><UiButton variant="ghost" @click="editor = null">Cancel</UiButton><UiButton :disabled="!editor.title.trim() || !editor.capability.trim()" data-testid="learn-v2-save-objective" @click="save">Save revision</UiButton></div></div><div class="mt-5 grid gap-5 lg:grid-cols-[minmax(0,1fr)_20rem]"><div class="overflow-hidden rounded-xl border border-border bg-card"><div class="border-b border-border px-4 py-3 text-sm text-muted-foreground"><Route class="mr-2 inline h-4 w-4 text-primary" />Ordered capability trail</div><ol class="divide-y divide-border"><li v-for="(objective, index) in objectives" :key="objective.id"><button type="button" class="flex w-full items-start gap-3 p-4 text-left transition-colors hover:bg-accent/30 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-inset focus-visible:ring-ring" :class="selected?.id === objective.id ? 'bg-primary/5' : ''" @click="emit('selectObjective', objective.id)"><GripVertical class="mt-0.5 h-4 w-4 shrink-0 text-muted-foreground" /><span class="flex h-6 w-6 shrink-0 items-center justify-center rounded-full border border-border font-inter text-xs text-muted-foreground">{{ index + 1 }}</span><span class="min-w-0 flex-1"><span class="flex flex-wrap items-center gap-x-2 gap-y-1"><span class="font-medium">{{ objective.title }}</span><span class="font-inter text-[11px]" :class="coverageClass[objective.coverage]">{{ objective.coverage }} evidence</span></span><span class="mt-1 block text-sm text-muted-foreground">{{ objective.capability }}</span><span class="mt-2 block font-inter text-xs text-muted-foreground">{{ objective.milestone }} · {{ stateLabel[objective.mastery] }}<template v-if="objective.effortMinutes"> · {{ objective.effortMinutes }} min</template></span></span><ArrowRight class="mt-1 h-4 w-4 text-muted-foreground" /></button></li></ol></div><aside v-if="selected" class="h-fit rounded-xl border border-border bg-card p-5 lg:sticky lg:top-4" data-testid="learn-v2-objective-inspector"><p class="font-inter text-xs uppercase tracking-wide text-muted-foreground">{{ selected.milestone }}</p><h3 class="mt-1 font-dm-sans text-lg font-semibold">{{ selected.title }}</h3><p class="mt-2 text-sm text-muted-foreground">{{ selected.detail ?? selected.capability }}</p><dl class="mt-5 space-y-3 text-sm"><div><dt class="text-xs text-muted-foreground">Assessment</dt><dd class="mt-1">{{ selected.assessment ?? 'Assessment contract pending review' }}</dd></div><div><dt class="text-xs text-muted-foreground">Prerequisites</dt><dd class="mt-1">{{ selected.prerequisiteIds?.length ? `${selected.prerequisiteIds.length} linked objective${selected.prerequisiteIds.length === 1 ? '' : 's'}` : 'None' }}</dd></div></dl><p v-if="selected.coverage === 'gap'" class="mt-4 flex gap-2 text-sm text-amber-200"><CircleAlert class="h-4 w-4 shrink-0" />Resolve this evidence gap before publishing this objective.</p><UiButton class="mt-5 w-full" variant="secondary" data-testid="learn-v2-map-edit-objective" @click="editSelected">Edit objective</UiButton></aside></div></section>
</template>
